/* PsychLogic — Full-Length Mock 14. Question bank. */
window.MOCK_QUESTIONS = [{"id": 1, "question": "Every evening Sapna has a strong craving and eats a very large amount of food quickly, then makes herself vomit and fasts the next day. Her weight is normal. The most likely diagnosis is:", "options": ["Anorexia nervosa, binge-purge type", "Pica", "Bulimia nervosa", "Binge-eating disorder"], "correctAnswer": 2, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Recurrent binge eating with compensatory behaviour (vomiting, fasting, laxatives), self-evaluation linked to body shape, and normal weight point to bulimia nervosa.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Anorexia nervosa, binge-purge type — Anorexia needs significantly low body weight.</li><li>(B) Pica — Pica is eating non-food substances.</li><li>(D) Binge-eating disorder — Binge-eating disorder has no regular compensatory behaviour.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>DSM-5 requires binges and compensation at least once a week for 3 months.</li><li>Gerald Russell described bulimia nervosa in 1979.</li></ul>", "examWatch": "This area has appeared in previous papers. It may well come in your exam too."}, {"id": 2, "question": "Eclectic counselling, which selects methods from different approaches to suit each client, was systematically proposed by:", "options": ["Frederick Thorne", "Allen Ivey", "E.G. Williamson", "Gerard Egan"], "correctAnswer": 0, "subject": "Counselling & psychotherapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Frederick C. Thorne (1950) argued for a scientific eclecticism, choosing directive or non-directive methods according to the client’s needs.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Allen Ivey — Ivey proposed the microskills hierarchy.</li><li>(C) E.G. Williamson — Williamson proposed directive counselling.</li><li>(D) Gerard Egan — Egan proposed the skilled helper model.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Lazarus’s multimodal therapy is ‘technical eclecticism’.</li><li>Integration combines theories; eclecticism combines techniques.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 3, "question": "Rohit repeatedly steals small items such as pens and keychains from shops even though he can easily pay for them and does not need them. He feels tension before the act and relief afterwards. The most likely diagnosis is:", "options": ["Malingering", "Conduct disorder", "Antisocial personality disorder", "Kleptomania"], "correctAnswer": 3, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Kleptomania is a recurrent failure to resist impulses to steal objects not needed for personal use or their money value, with rising tension before and relief after.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Malingering — Malingering is faking illness for gain.</li><li>(B) Conduct disorder — Conduct disorder begins in childhood and involves many rule violations.</li><li>(C) Antisocial personality disorder — Antisocial PD involves broad disregard for others’ rights, often for gain.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Kleptomania is in DSM-5’s disruptive, impulse-control and conduct disorders chapter.</li><li>Pyromania (fire-setting) is in the same chapter.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this concept has been asked before in different forms — revise the related points as well."}, {"id": 4, "question": "In Allen Ivey’s microskills hierarchy, the foundation on which all other counselling skills are built is:", "options": ["Reflection of meaning", "Attending behaviour", "Confrontation", "Skill integration"], "correctAnswer": 1, "subject": "Counselling & psychotherapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Ivey’s hierarchy starts with ethics, multicultural competence and wellness, then attending behaviour (eye contact, body language, vocal qualities, verbal tracking), and moves up to listening, influencing and integration skills.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Reflection of meaning — Reflection of meaning is higher up.</li><li>(C) Confrontation — Confrontation is a higher-level skill.</li><li>(D) Skill integration — Skill integration is at the top.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Ivey developed microcounselling in the late 1960s.</li><li>Microskills training uses video practice and feedback.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 5, "question": "<span class=\"pyq-badge\">PYQ</span>The ‘start-stop technique’ and the ‘squeeze technique’ are useful in the treatment of:", "options": ["Male erectile disorder", "Premature ejaculation", "Inhibited male orgasm", "Vaginismus"], "correctAnswer": 1, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Semans’ start-stop technique (1956) and Masters and Johnson’s squeeze technique help men learn to recognise and delay the point of ejaculation.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Male erectile disorder — Erectile disorder is treated with sensate focus and medical options.</li><li>(C) Inhibited male orgasm — Delayed (inhibited) orgasm needs different methods.</li><li>(D) Vaginismus — Vaginismus is treated with graded vaginal dilators and relaxation.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Sensate focus (Masters and Johnson) reduces performance anxiety.</li><li>SSRIs are sometimes used to delay ejaculation.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 6, "question": "At a noisy party you are focused on one conversation but immediately notice when someone across the room says your name. This is known as:", "options": ["Change blindness", "The Stroop effect", "Inattentional blindness", "The cocktail party effect"], "correctAnswer": 3, "subject": "General psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Colin Cherry (1953) described the cocktail party problem. Hearing one’s own name in an unattended channel (Moray, 1959) shows that some unattended information is processed for meaning.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Change blindness — Change blindness is missing changes in a scene.</li><li>(B) The Stroop effect — The Stroop effect is interference between word and colour.</li><li>(C) Inattentional blindness — Inattentional blindness is missing obvious things when attention is elsewhere (‘invisible gorilla’).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>This finding challenged Broadbent’s early, all-or-none filter.</li><li>Cherry used dichotic listening and shadowing tasks.</li></ul>", "examWatch": "Asked in earlier papers; examiners like to test it through a case or a NOT question."}, {"id": 7, "question": "Gerard Egan’s ‘Skilled Helper’ model organises the helping process into three stages:", "options": ["Exploration, insight and termination only", "Rapport, transference and interpretation", "Current scenario, preferred scenario, and the way forward (action)", "Assessment, diagnosis and medication"], "correctAnswer": 2, "subject": "Counselling & psychotherapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Egan’s three stages: (1) What is going on? (current scenario), (2) What do I want instead? (preferred scenario), (3) How do I get there? (action strategies).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Exploration, insight and termination only — This is a vague general description, not Egan’s model.</li><li>(B) Rapport, transference and interpretation — Transference and interpretation belong to psychodynamic therapy.</li><li>(D) Assessment, diagnosis and medication — Diagnosis and medication are medical steps.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Hill’s three-stage model is: exploration, insight, action.</li><li>Egan stresses the client’s blind spots and leverage.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 8, "question": "In DSM-5, insomnia disorder requires sleep difficulty on at least 3 nights a week for at least:", "options": ["3 months", "6 months", "1 month", "2 weeks"], "correctAnswer": 0, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Insomnia disorder needs difficulty starting or maintaining sleep (or early waking) at least 3 nights a week for at least 3 months, despite adequate opportunity to sleep.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) 6 months — 6 months is not required.</li><li>(C) 1 month — 1 month was the DSM-IV duration.</li><li>(D) 2 weeks — 2 weeks is too short.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>CBT for insomnia is the first-line treatment.</li><li>Episodic insomnia lasts 1–3 months.</li></ul>", "examWatch": "Questions on this have come before — a quick revision here pays off."}, {"id": 9, "question": "T-scores, often used in personality inventories such as the MMPI, have a mean and standard deviation of:", "options": ["50 and 10", "5 and 2", "0 and 1", "100 and 15"], "correctAnswer": 0, "subject": "Psychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> T-scores are standard scores with a mean of 50 and SD of 10. On the MMPI, a T-score of 65 or more is usually treated as clinically significant.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) 5 and 2 — Mean 5 and SD 2 are stanines.</li><li>(C) 0 and 1 — Mean 0 and SD 1 are z-scores.</li><li>(D) 100 and 15 — Mean 100 and SD 15 are deviation IQ scores.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>T = 50 + 10z.</li><li>T-scores avoid negative numbers and decimals.</li></ul>", "examWatch": "Seen in past papers more than once. Know the difference between the options well."}, {"id": 10, "question": "In Strack’s (1988) study, people who held a pen between their teeth (forcing a smile) rated cartoons as funnier than people who held it between their lips. This supports the:", "options": ["Cannon–Bard theory", "Facial feedback hypothesis", "Two-factor theory", "Opponent-process theory"], "correctAnswer": 1, "subject": "General psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The facial feedback hypothesis (Tomkins, later tested by Strack, Martin and Stepper) says that facial expressions can influence the emotions we feel.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Cannon–Bard theory — Cannon–Bard says arousal and emotion occur at the same time through the thalamus.</li><li>(C) Two-factor theory — The two-factor theory (Schachter and Singer) stresses cognitive labelling of arousal.</li><li>(D) Opponent-process theory — Opponent-process theory explains after-reactions to emotions.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The finding was not replicated in a large 2016 replication project, so the effect is debated.</li><li>James–Lange theory is a broader version of the same idea.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 11, "question": "A young man who has been using a stimulant drug heavily for several days feels that insects are crawling under his skin and keeps scratching himself. This tactile hallucination is called:", "options": ["Haptic illusion", "Paraesthesia", "Kinaesthetic hallucination", "Formication"], "correctAnswer": 3, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Formication (from the Latin for ant) is the false feeling of insects crawling on or under the skin. It is classic in cocaine (‘cocaine bugs’) and amphetamine use, and in alcohol withdrawal.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Haptic illusion — A haptic illusion is a misperception of a real touch.</li><li>(B) Paraesthesia — Paraesthesia is tingling or ‘pins and needles’ from nerve problems.</li><li>(C) Kinaesthetic hallucination — Kinaesthetic hallucinations are false feelings of movement.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Delusional parasitosis is a fixed belief of infestation.</li><li>Stimulant psychosis can resemble paranoid schizophrenia.</li></ul>", "examWatch": "This area has appeared in previous papers. It may well come in your exam too."}, {"id": 12, "question": "Carl Rogers’ early approach, described in Counseling and Psychotherapy (1942), was called:", "options": ["Rational counselling", "Directive counselling", "Non-directive counselling", "Eclectic counselling"], "correctAnswer": 2, "subject": "Counselling & psychotherapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Rogers first called his approach non-directive: the client, not the counsellor, leads. It later became client-centred and then person-centred therapy.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Rational counselling — ‘Rational counselling’ is not Rogers’ term.</li><li>(B) Directive counselling — Directive counselling is Williamson’s approach.</li><li>(D) Eclectic counselling — Eclectic counselling is Thorne’s approach.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Client-Centered Therapy was published in 1951.</li><li>Core conditions: empathy, congruence and unconditional positive regard.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 13, "question": "A researcher systematically codes newspaper reports of suicide for themes such as method, cause and stigma, and counts how often each appears. This method is:", "options": ["Content analysis", "Experiment", "Sociometry", "Case study"], "correctAnswer": 0, "subject": "Research methods & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Content analysis studies communication (texts, media, speeches) by coding and counting categories in a systematic way.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Experiment — An experiment manipulates variables.</li><li>(C) Sociometry — Sociometry maps relationships in a group.</li><li>(D) Case study — A case study looks in depth at one person or unit.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Content analysis can be quantitative or qualitative.</li><li>Inter-coder reliability (e.g. kappa) checks coding consistency.</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 14, "question": "When testing a child on a Binet-type scale, the examiner first finds the highest age level at which all items are passed (basal age) and continues until all items at a level are failed. That upper level is the:", "options": ["Chronological age", "Mental age", "Ceiling age", "Deviation age"], "correctAnswer": 2, "subject": "Psychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The basal age is where all items are passed; the ceiling age is where all are failed. Credits between them are added to the basal age to give mental age.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Chronological age — Chronological age is actual age.</li><li>(B) Mental age — Mental age is the final calculated result.</li><li>(D) Deviation age — ‘Deviation age’ is not a standard term.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Basal and ceiling rules save testing time.</li><li>Modern scales use basal and ceiling rules for each subtest.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 15, "question": "In Wickens’s ‘release from proactive interference’ studies, recall fell over several trials of fruit names, but improved sharply when the category switched to professions. This shows that:", "options": ["Short-term memory stores only sounds, not meanings", "Proactive interference depends on similarity of meaning, so a change of category reduces it", "Memory decays with time regardless of content", "Retroactive interference is stronger than proactive interference"], "correctAnswer": 1, "subject": "General psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Delos Wickens (1970s) showed proactive interference builds up with similar items and is ‘released’ when the category changes — evidence that meaning is encoded even in short-term memory.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Short-term memory stores only sounds, not meanings — The category effect shows meaning is encoded.</li><li>(C) Memory decays with time regardless of content — The sudden improvement shows interference, not simple decay.</li><li>(D) Retroactive interference is stronger than proactive interference — The study was about proactive, not retroactive, interference.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>It uses the Brown–Peterson task.</li><li>Proactive interference: old learning disrupts new; retroactive: new disrupts old.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 16, "question": "Walking alone without support is usually achieved by most infants around:", "options": ["6 months", "2 years and 6 months", "20 months", "12 to 15 months"], "correctAnswer": 3, "subject": "Developmental psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Most infants walk alone at about 12–15 months, after pulling to stand and ‘cruising’ along furniture.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) 6 months — At 6 months infants are just beginning to sit with support.</li><li>(B) 2 years and 6 months — 2½ years would be a clear delay.</li><li>(C) 20 months — 20 months is later than usual (still within the normal range for some).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Gross motor milestones follow a head-to-toe (cephalocaudal) order.</li><li>The Denver Developmental Screening Test checks milestones.</li></ul>", "examWatch": "Not asked directly yet, but it sits right next to frequently asked topics — it may appear in a new form."}, {"id": 17, "question": "<p class=\"stem-lead\">Read the Assertion (A) and Reason (R) and choose the correct option:</p><div class=\"ar-block\"><div class=\"ar-row\"><span class=\"ar-label\">Assertion (A)</span><span class=\"ar-text\">People usually remember the content of their nightmares in detail.</span></div><div class=\"ar-row\"><span class=\"ar-label\">Reason (R)</span><span class=\"ar-text\">Nightmares occur mainly during REM sleep, from which the person wakes up quickly and fully alert.</span></div></div>", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "correctAnswer": 0, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Both are true, and R explains A. Nightmares arise in REM sleep (mostly in the second half of the night), and the person wakes fully, so the dream is recalled. Sleep terrors arise from deep NREM sleep and are usually not remembered.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>B is wrong because R explains A.</li><li>C is wrong because R is true.</li><li>D is wrong because A is true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Nightmare disorder is in DSM-5’s sleep–wake disorders chapter.</li><li>Imagery rehearsal therapy treats recurrent nightmares.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 18, "question": "The Seguin Form Board, in which a child fits shaped blocks into matching holes as quickly as possible, is a:", "options": ["Projective test", "Personality inventory", "Performance test of intelligence", "Test of reading ability"], "correctAnswer": 2, "subject": "Psychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The Seguin Form Board (Édouard Séguin, 1866) is a non-verbal performance test, often used with young children and people with intellectual disability.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Projective test — It is not projective.</li><li>(B) Personality inventory — It is not a personality inventory.</li><li>(D) Test of reading ability — It does not need reading.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>It is part of several Indian performance batteries.</li><li>Séguin pioneered education of children with intellectual disability.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this concept has been asked before in different forms — revise the related points as well."}, {"id": 19, "question": "An 80-year-old man living alone is found in a filthy house full of rubbish, with no interest in his own hygiene. He refuses help and shows no shame about his living conditions. This picture of extreme self-neglect is known as:", "options": ["Cotard’s syndrome", "Diogenes syndrome", "Ganser syndrome", "Charles Bonnet syndrome"], "correctAnswer": 1, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Diogenes syndrome (senile squalor syndrome, Clark and colleagues, 1975) is severe self-neglect, domestic squalor, hoarding and refusal of help, usually in older people.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Cotard’s syndrome — Cotard’s syndrome is nihilistic delusions.</li><li>(C) Ganser syndrome — Ganser syndrome is approximate answers.</li><li>(D) Charles Bonnet syndrome — Charles Bonnet syndrome is visual hallucinations in visually impaired people.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>It is often linked with frontal-lobe dysfunction or dementia.</li><li>It is named after the Greek philosopher Diogenes, who lived in a barrel.</li></ul>", "examWatch": "Asked in earlier papers; examiners like to test it through a case or a NOT question."}, {"id": 20, "question": "The scale that asks how close a relationship a person would accept with members of another group — from marriage down to excluding them from the country — was developed by:", "options": ["Rensis Likert", "Charles Osgood", "Louis Thurstone", "Emory Bogardus"], "correctAnswer": 3, "subject": "Psychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The Bogardus Social Distance Scale (1925) measures prejudice by the degree of closeness accepted with members of other groups.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Rensis Likert — Likert developed summated rating scales.</li><li>(B) Charles Osgood — Osgood developed the semantic differential.</li><li>(C) Louis Thurstone — Thurstone developed equal-appearing interval scales.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>It is a cumulative scale: accepting a close relation implies accepting more distant ones.</li><li>Used to study ethnic and caste attitudes.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a likely new area. Learn the key points above."}, {"id": 21, "question": "Workers’ productivity rose whenever lighting was changed — whether it was made brighter or dimmer — because they knew they were being studied. This is the:", "options": ["Hawthorne effect", "Pygmalion effect", "Halo effect", "Placebo effect"], "correctAnswer": 0, "subject": "Research methods & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The Hawthorne studies (Western Electric, 1924–1932; Mayo and colleagues) gave their name to changes in behaviour caused by being observed.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Pygmalion effect — The Pygmalion effect is others’ expectations shaping performance.</li><li>(C) Halo effect — The halo effect is one trait colouring overall judgement.</li><li>(D) Placebo effect — The placebo effect comes from expecting a treatment to work.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Reactivity is a threat to validity in observational research.</li><li>Unobtrusive measures reduce reactivity.</li></ul>", "examWatch": "Questions on this have come before — a quick revision here pays off."}, {"id": 22, "question": "In Rosenthal and Jacobson’s classroom study, children whom teachers were told were ‘late bloomers’ showed greater IQ gains by the end of the year. This illustrates the:", "options": ["Hawthorne effect", "Pygmalion effect (self-fulfilling prophecy)", "Placebo effect", "Halo effect"], "correctAnswer": 1, "subject": "Social psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> In Pygmalion in the Classroom (1968), teachers’ raised expectations (based on randomly chosen names) seemed to boost the children’s performance — a self-fulfilling prophecy.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Hawthorne effect — The Hawthorne effect is change from being observed.</li><li>(C) Placebo effect — The placebo effect is improvement from expecting a treatment to work.</li><li>(D) Halo effect — The halo effect is one trait colouring overall judgement.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Robert Merton coined ‘self-fulfilling prophecy’ (1948).</li><li>The ‘Golem effect’ is the negative version.</li></ul>", "examWatch": "Seen in past papers more than once. Know the difference between the options well."}, {"id": 23, "question": "A patient believes that he has turned into a wolf and howls at night. This rare delusion is called:", "options": ["Amok", "Koro", "Clinical lycanthropy", "Zoopsia"], "correctAnswer": 2, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Clinical lycanthropy is the delusion of being transformed into an animal, classically a wolf. It is usually seen in psychotic depression, schizophrenia or bipolar disorder.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Amok — Amok is a sudden episode of violent behaviour.</li><li>(B) Koro — Koro is fear that the genitals are shrinking into the body.</li><li>(D) Zoopsia — Zoopsia is seeing (hallucinating) animals, as in delirium.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>It is a delusional misidentification of the self.</li><li>Koro and amok are culture-related syndromes.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 24, "question": "Match the researcher (List I) with the study or tool (List II): List I: 1. Konrad Lorenz   2. Eleanor Gibson and Richard Walk   3. T. Berry Brazelton   4. Virginia Apgar List II: a. Newborn scoring of heart rate, breathing, muscle tone, reflexes and colour   b. Neonatal Behavioural Assessment Scale   c. Imprinting in goslings   d. The visual cliff", "options": ["1-d, 2-c, 3-b, 4-a", "1-c, 2-d, 3-a, 4-b", "1-c, 2-b, 3-d, 4-a", "1-c, 2-d, 3-b, 4-a"], "correctAnswer": 3, "subject": "Developmental psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Lorenz – imprinting (goslings followed him); Gibson and Walk (1960) – the visual cliff for depth perception; Brazelton – NBAS (1973), assessing newborn behaviour; Apgar (1952) – the Apgar score at 1 and 5 minutes after birth.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other codes swap Lorenz with Gibson and Walk, or Brazelton with Apgar.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Imprinting has a critical period in the first days of life.</li><li>An Apgar score of 7–10 is normal.</li></ul>", "examWatch": "This area has appeared in previous papers. It may well come in your exam too."}, {"id": 25, "question": "In DSM-5, the diagnosis ‘gender identity disorder’ was replaced by:", "options": ["Sexual identity disorder", "Gender incongruence", "Gender dysphoria", "Transvestic disorder"], "correctAnswer": 2, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> DSM-5 (2013) replaced ‘gender identity disorder’ with ‘gender dysphoria’, focusing on the distress rather than the identity itself.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Sexual identity disorder — ‘Sexual identity disorder’ is not a DSM term.</li><li>(B) Gender incongruence — ‘Gender incongruence’ is the ICD-11 term, placed outside the mental disorders chapter.</li><li>(D) Transvestic disorder — Transvestic disorder is a paraphilic disorder.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>ICD-11 moved gender incongruence to the chapter on sexual health.</li><li>DSM-5 has separate criteria for children and for adolescents/adults.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this concept has been asked before in different forms — revise the related points as well."}, {"id": 26, "question": "After solving several water-jar problems with a long formula, students keep using the same long method even when a much simpler solution exists. Abraham Luchins called this:", "options": ["Functional fixedness", "Mental set (Einstellung effect)", "Confirmation bias", "Insight"], "correctAnswer": 1, "subject": "General psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The Einstellung effect (Luchins, 1942) is a mental set: a method that worked before is applied rigidly, blocking simpler solutions.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Functional fixedness — Functional fixedness is about seeing objects only in their usual use.</li><li>(C) Confirmation bias — Confirmation bias is seeking evidence that supports one’s beliefs.</li><li>(D) Insight — Insight is a sudden new understanding — the opposite of this rigidity.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Einstellung means ‘setting’ or ‘attitude’ in German.</li><li>Incubation (taking a break) can help break a mental set.</li></ul>", "examWatch": "Asked in earlier papers; examiners like to test it through a case or a NOT question."}, {"id": 27, "question": "Most adults cannot recall events from before about age 3 or 4. This is known as:", "options": ["Infantile (childhood) amnesia", "Source amnesia", "Repression", "Retrograde amnesia"], "correctAnswer": 0, "subject": "Developmental psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Infantile amnesia is the normal absence of memories from early childhood, linked with brain maturation (hippocampus, prefrontal cortex) and the development of language and self-concept.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Source amnesia — Source amnesia is forgetting where information came from.</li><li>(C) Repression — Repression is a Freudian defence; Freud did explain infantile amnesia this way, but it is not the modern view.</li><li>(D) Retrograde amnesia — Retrograde amnesia follows brain injury.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Freud first named ‘infantile amnesia’.</li><li>Children’s own early memories fade around age 7 (‘childhood amnesia’ develops).</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 28, "question": "<span class=\"pyq-badge\">PYQ</span>The tendency to think of objects only in terms of their usual use, which can block problem solving, is called:", "options": ["Mental barrier", "Functional fixedness", "Einstellung", "Trial and error"], "correctAnswer": 1, "subject": "General psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Functional fixedness (Karl Duncker’s candle problem, 1945) is seeing an object only in its usual function — e.g. not thinking to use a box of tacks as a candle holder.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Mental barrier — ‘Mental barrier’ is not the technical term.</li><li>(C) Einstellung — Einstellung is a fixed mental set from past solutions, not about object use.</li><li>(D) Trial and error — Trial and error is a problem-solving method.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Maier’s two-string problem shows a similar block.</li><li>Insight often involves overcoming functional fixedness.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 29, "question": "Glick and Fiske described ‘benevolent sexism’, which is:", "options": ["Open hostility towards women", "Prejudice against men", "Equal treatment of men and women", "Seemingly positive but patronising beliefs that women need protection and are pure or delicate"], "correctAnswer": 3, "subject": "Social psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Ambivalent sexism (1996) has two parts: hostile sexism (antagonism) and benevolent sexism (protective, idealising but restrictive attitudes). Both support gender inequality.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Open hostility towards women — Open hostility is hostile sexism.</li><li>(B) Prejudice against men — Prejudice against men is not this concept.</li><li>(C) Equal treatment of men and women — Equal treatment is not sexism.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The Ambivalent Sexism Inventory measures both parts.</li><li>Benevolent sexism can seem flattering, which makes it harder to challenge.</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 30, "question": "A researcher runs 5 separate t-tests on the same data and wants to keep the overall Type I error at .05. Using the Bonferroni correction, each test should use an alpha level of:", "options": [".01", ".05", ".25", ".001"], "correctAnswer": 0, "subject": "Research methods & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Bonferroni: divide the overall alpha by the number of tests — .05 ÷ 5 = .01.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) .05 — .05 for each test would inflate the overall error rate.</li><li>(C) .25 — .25 is .05 × 5, the wrong direction.</li><li>(D) .001 — .001 is stricter than needed.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Bonferroni is simple but conservative (lowers power).</li><li>ANOVA with post-hoc tests is often better than many t-tests.</li></ul>", "examWatch": "Questions on this have come before — a quick revision here pays off."}, {"id": 31, "question": "A counsellor says, ‘You say you are fine with the divorce, but each time you mention it your voice shakes and you look away.’ The counsellor is using:", "options": ["Reassurance", "Interpretation of dreams", "Confrontation", "Advice-giving"], "correctAnswer": 2, "subject": "Counselling & psychotherapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Confrontation (or challenging) gently points out discrepancies between the client’s words and behaviour, or between statements, to promote awareness.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Reassurance — Reassurance tries to comfort, not to highlight a discrepancy.</li><li>(B) Interpretation of dreams — Dream interpretation is a psychodynamic technique.</li><li>(D) Advice-giving — Advice-giving tells the client what to do.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Confrontation should be tentative and supportive.</li><li>It is one of Ivey’s influencing skills.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 32, "question": "<span class=\"pyq-badge\">PYQ</span>Who developed the Filter-attenuation theory?", "options": ["Broadbent", "Triesman", "Johnston", "Heinz"], "correctAnswer": 1, "subject": "General psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Anne Treisman (1964) proposed that unattended messages are not blocked completely but weakened (attenuated), so important words such as one’s name can still get through.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Broadbent — Broadbent proposed the earlier all-or-none filter (1958).</li><li>(C) Johnston — Johnston and Heinz proposed a flexible ‘multimode’ theory.</li><li>(D) Heinz — Heinz worked with Johnston on that model.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Deutsch and Deutsch proposed a late-selection model.</li><li>Shadowing tasks (Cherry) were used in these studies.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 33, "question": "Match the technique (List I) with its developer (List II): List I: 1. Q-sort   2. Sociometry (sociogram)   3. Children’s Apperception Test   4. Social Desirability Scale List II: a. Crowne and Marlowe   b. Leopold Bellak   c. Jacob Moreno   d. William Stephenson", "options": ["1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b", "1-d, 2-b, 3-c, 4-a", "1-d, 2-c, 3-b, 4-a"], "correctAnswer": 3, "subject": "Psychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Q-sort – William Stephenson (1953), later used by Rogers to measure the gap between real and ideal self; Sociometry – Jacob Moreno (1934); Children’s Apperception Test – Leopold and Sonya Bellak (1949), using animal figures; Social Desirability Scale – Crowne and Marlowe (1960).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other codes swap Stephenson with Moreno, or Bellak with Crowne and Marlowe.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Rogers used the Q-sort to show self–ideal congruence rising during therapy.</li><li>Social desirability bias is a major problem in self-report tests.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 34, "question": "<span class=\"pyq-badge\">PYQ</span>Parameter is characteristic of:", "options": ["The sample", "The population", "An individual", "A test"], "correctAnswer": 1, "subject": "Research methods & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> A parameter (e.g. μ, σ) describes a population; a statistic (e.g. x̄, s) describes a sample and is used to estimate the parameter.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) The sample — A characteristic of a sample is a statistic.</li><li>(C) An individual — An individual has scores, not parameters.</li><li>(D) A test — A test has properties such as reliability, not parameters in this sense.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Inferential statistics use sample statistics to estimate population parameters.</li><li>Parametric tests assume conditions about population distributions.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 35, "question": "In DSM-5, somatic symptom disorder requires that the state of being symptomatic is persistent, typically for more than:", "options": ["6 months", "1 month", "3 months", "2 years"], "correctAnswer": 0, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Somatic symptom disorder needs distressing somatic symptoms with excessive thoughts, feelings or behaviours about them; the symptomatic state usually lasts more than 6 months, even if individual symptoms change.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) 1 month — 1 month is too short.</li><li>(C) 3 months — 3 months is not the rule.</li><li>(D) 2 years — 2 years is not the rule.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>SSD replaced somatization disorder and much of hypochondriasis.</li><li>Symptoms need not be ‘medically unexplained’ in DSM-5.</li></ul>", "examWatch": "Seen in past papers more than once. Know the difference between the options well."}, {"id": 36, "question": "Coie and Dodge classified children’s peer status using sociometric ratings. A child who receives few ‘like most’ and few ‘like least’ nominations — not disliked, simply overlooked — is:", "options": ["Popular", "Controversial", "Rejected", "Neglected"], "correctAnswer": 3, "subject": "Developmental psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Coie, Dodge and Coppotelli (1982) described popular, rejected, neglected, controversial and average children. Neglected children are rarely nominated either way.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Popular — Popular children get many ‘like most’ nominations.</li><li>(B) Controversial — Controversial children get many of both.</li><li>(C) Rejected — Rejected children get many ‘like least’ nominations.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Rejected children are at higher risk of later problems than neglected children.</li><li>Sociometry was developed by Jacob Moreno.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 37, "question": "The Kuder Preference Record, widely used in career guidance, mainly measures:", "options": ["Neuropsychological deficits", "Intelligence", "Vocational interests", "Personality disorders"], "correctAnswer": 2, "subject": "Psychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> G. Frederic Kuder’s Preference Record (1939) asks people to choose among activities in forced-choice triads, giving scores on interest areas such as mechanical, scientific and artistic.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Neuropsychological deficits — Neuropsychological deficits are assessed with batteries such as the NIMHANS battery.</li><li>(B) Intelligence — Intelligence is measured by tests such as WAIS.</li><li>(D) Personality disorders — Personality disorders are assessed with tools such as the MCMI.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The Strong Interest Inventory is another major interest test.</li><li>Interest is different from aptitude.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 38, "question": "<span class=\"pyq-badge\">PYQ</span>A complete count of every member of a population, such as the national ‘Census’, is an example of which method?", "options": ["Ex post facto", "Field study", "Survey", "Sociometry"], "correctAnswer": 2, "subject": "Research methods & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> A census is a survey of the whole population, collecting standard information from everyone rather than from a sample.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Ex post facto — Ex post facto research studies effects of variables that have already occurred.</li><li>(B) Field study — A field study observes behaviour in natural settings.</li><li>(D) Sociometry — Sociometry maps relationships within groups.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Sample surveys are used when a census is too costly.</li><li>India’s census is held every 10 years.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 39, "question": "<span class=\"pyq-badge\">PYQ</span>Hypnagogic hallucinations most commonly occur in:", "options": ["Schizophrenia", "Delirium", "Drug dependence", "Normal individuals"], "correctAnswer": 3, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Hypnagogic (falling asleep) and hypnopompic (waking up) hallucinations are common in healthy people and are not by themselves a sign of illness.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Schizophrenia — In schizophrenia, hallucinations occur in full wakefulness.</li><li>(B) Delirium — In delirium, hallucinations come with clouded consciousness.</li><li>(C) Drug dependence — They are not typical of drug dependence.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Frequent hypnagogic hallucinations with sleep attacks suggest narcolepsy.</li><li>They are not counted as psychotic symptoms.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 40, "question": "<span class=\"pyq-badge\">PYQ</span>Distress tolerance is a major treatment component of:", "options": ["Behaviour therapy", "Dialectical Behaviour therapy", "Cognitive Behaviour Therapy", "Psychodynamic therapy"], "correctAnswer": 1, "subject": "Counselling & psychotherapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Distress tolerance is one of the four DBT skills modules (with mindfulness, emotion regulation and interpersonal effectiveness). It teaches surviving crises without making them worse (e.g. TIPP, radical acceptance).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Behaviour therapy — General behaviour therapy has no ‘distress tolerance’ module.</li><li>(C) Cognitive Behaviour Therapy — Standard CBT does not use this as a named module.</li><li>(D) Psychodynamic therapy — Psychodynamic therapy works through insight.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>DBT was developed by Marsha Linehan for borderline personality disorder.</li><li>‘Radical acceptance’ is a distress tolerance skill.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 41, "question": "Women students who were told that a maths test showed gender differences scored lower than equally able women who were told the test was gender-neutral. This effect is called:", "options": ["Stereotype threat", "Learned helplessness", "Self-serving bias", "Social loafing"], "correctAnswer": 0, "subject": "Social psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Stereotype threat (Steele and Aronson, 1995) is the anxiety of possibly confirming a negative stereotype about one’s group, which can lower performance.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Learned helplessness — Learned helplessness follows uncontrollable events.</li><li>(C) Self-serving bias — Self-serving bias is taking credit for success and blaming failure on outside factors.</li><li>(D) Social loafing — Social loafing is reduced effort in groups.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Steele and Aronson first studied it with African American students.</li><li>Reducing the threat (e.g. reframing the test) improves performance.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 42, "question": "After her last child leaves home for college, Sunita, 50, feels sad, lonely and unsure of her purpose. This experience is popularly called:", "options": ["Mid-life crisis", "Role reversal", "Empty nest syndrome", "Sandwich generation"], "correctAnswer": 2, "subject": "Developmental psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> ‘Empty nest syndrome’ describes feelings of sadness and loss when children leave home. Many parents also report improved marital satisfaction afterwards.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Mid-life crisis — A mid-life crisis is a broader questioning of life goals.</li><li>(B) Role reversal — Role reversal is when children care for ageing parents.</li><li>(D) Sandwich generation — The ‘sandwich generation’ cares for both children and ageing parents.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>It is not a formal diagnosis.</li><li>‘Boomerang children’ return home after leaving.</li></ul>", "examWatch": "This area has appeared in previous papers. It may well come in your exam too."}, {"id": 43, "question": "A client says, ‘My boss shouted at me again in front of everyone.’ The counsellor replies, ‘You felt humiliated and angry.’ This response is an example of:", "options": ["Probing", "Summarising", "Paraphrasing of content", "Reflection of feeling"], "correctAnswer": 3, "subject": "Counselling & psychotherapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Reflection of feeling names the emotion behind the client’s words, showing empathic understanding.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Probing — Probing asks for more information.</li><li>(B) Summarising — Summarising pulls together several points.</li><li>(C) Paraphrasing of content — Paraphrasing restates the content (facts), not mainly the feeling.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Reflection is central to person-centred counselling.</li><li>Accurate reflection is a sign of primary empathy (Egan).</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 44, "question": "<p class=\"stem-lead\">Read the Assertion (A) and Reason (R) and choose the correct option:</p><div class=\"ar-block\"><div class=\"ar-row\"><span class=\"ar-label\">Assertion (A)</span><span class=\"ar-text\">Increasing the sample size makes the standard error of the mean smaller.</span></div><div class=\"ar-row\"><span class=\"ar-label\">Reason (R)</span><span class=\"ar-text\">The standard error of the mean equals the standard deviation divided by the square root of the sample size.</span></div></div>", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "correctAnswer": 0, "subject": "Research methods & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Both are true, and R explains A. Since SE = SD ÷ √n, a bigger n gives a smaller SE — the sample mean becomes a more precise estimate.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>B is wrong because R explains A.</li><li>C is wrong because R is true.</li><li>D is wrong because A is true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>To halve the SE you must quadruple the sample size.</li><li>The standard error of measurement (SEM) is a different idea, about test scores.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 45, "question": "Robert Selman’s stages of social perspective-taking describe how children develop the ability to:", "options": ["Understand other people’s points of view and feelings", "Use grammar correctly", "Form secure attachments", "Conserve quantity and number"], "correctAnswer": 0, "subject": "Developmental psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Selman (1980) described five levels from undifferentiated (egocentric) to societal perspective-taking, linked to friendships and social problem solving.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Use grammar correctly — Grammar development is a language topic.</li><li>(C) Form secure attachments — Attachment is Bowlby’s and Ainsworth’s concept.</li><li>(D) Conserve quantity and number — Conservation is Piaget’s concept.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Perspective-taking is related to theory of mind.</li><li>Selman applied his stages to friendship and peer conflict.</li></ul>", "examWatch": "A fresh, predicted question. The neighbouring topics are asked often, so it is worth knowing."}, {"id": 46, "question": "<span class=\"pyq-badge\">PYQ</span>Following are negative features of schizophrenia EXCEPT:", "options": ["Avolition", "Alogia", "Ambivalence", "Affective blunting"], "correctAnswer": 2, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Avolition (lack of drive), alogia (poverty of speech) and affective blunting are negative symptoms. Ambivalence (holding opposite feelings at once) is one of Bleuler’s four A’s but is not a negative symptom in the modern sense.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Avolition — Avolition is a negative symptom.</li><li>(B) Alogia — Alogia is a negative symptom.</li><li>(D) Affective blunting — Affective blunting is a negative symptom.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Other negative symptoms: anhedonia and asociality.</li><li>Andreasen’s SANS rates negative symptoms.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 47, "question": "A test that measures what a person has already learned in a subject, such as a final mathematics exam, is a(n):", "options": ["Interest inventory", "Projective test", "Aptitude test", "Achievement test"], "correctAnswer": 3, "subject": "Psychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Achievement tests measure past learning; aptitude tests predict future learning or performance.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Interest inventory — Interest inventories measure likes and dislikes for activities.</li><li>(B) Projective test — Projective tests assess personality through ambiguous stimuli.</li><li>(C) Aptitude test — Aptitude tests predict potential for future learning.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Intelligence tests are a kind of broad aptitude test.</li><li>Diagnostic tests locate specific learning difficulties.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 48, "question": "Anita, 28, cannot make everyday decisions without her mother’s advice, agrees with others to avoid losing their support, and feels helpless when alone. She urgently seeks a new relationship whenever one ends. The most likely diagnosis is:", "options": ["Avoidant personality disorder", "Dependent personality disorder", "Borderline personality disorder", "Histrionic personality disorder"], "correctAnswer": 1, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Dependent personality disorder (Cluster C) is a pervasive need to be taken care of, with submissive, clinging behaviour and fear of separation.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Avoidant personality disorder — Avoidant individuals avoid relationships for fear of rejection, rather than clinging to others.</li><li>(C) Borderline personality disorder — Borderline PD involves unstable mood, identity, impulsivity and self-harm.</li><li>(D) Histrionic personality disorder — Histrionic PD involves attention-seeking and shallow, dramatic emotion.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Cluster C: avoidant, dependent, obsessive-compulsive personality disorders.</li><li>Assertiveness training is often part of treatment.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 49, "question": "In the Ames room, a person standing in one corner looks like a giant and a person in the other corner looks tiny. This illusion works because:", "options": ["The eyes converge more on one person", "The two people are actually very different in height", "The room is trapezoidal but is assumed to be rectangular, so size constancy misleads us", "Light is refracted differently on each side"], "correctAnswer": 2, "subject": "General psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Adelbert Ames designed a distorted room that looks normal from one peephole. Because the brain assumes the room is rectangular, it judges both people to be at the same distance and misjudges their size.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) The eyes converge more on one person — Convergence does not explain it.</li><li>(B) The two people are actually very different in height — The people may be of the same height.</li><li>(D) Light is refracted differently on each side — No refraction effect is involved.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>It shows how assumptions (top-down knowledge) shape perception.</li><li>The Ponzo and Müller-Lyer illusions also involve misapplied size–distance cues.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 50, "question": "The Kohs Block Design Test, in which the person copies coloured designs using blocks, is mainly a measure of:", "options": ["Non-verbal intelligence and visuospatial ability", "Vocational interest", "Verbal comprehension", "Personality traits"], "correctAnswer": 0, "subject": "Psychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Samuel Kohs (1920) developed the block design test as a non-verbal intelligence measure. The Wechsler scales later adopted a Block Design subtest.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Vocational interest — Interests need interest inventories.</li><li>(C) Verbal comprehension — Verbal comprehension needs language-based tests.</li><li>(D) Personality traits — Personality needs personality tests.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Block design is sensitive to right parietal damage.</li><li>Kohs blocks are part of Bhatia’s performance battery in India.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this concept has been asked before in different forms — revise the related points as well."}, {"id": 51, "question": "Arrange Donald Super’s life-span career development stages in the correct order: I. Establishment II. Exploration III. Decline (disengagement) IV. Growth V. Maintenance", "options": ["II, IV, I, V, III", "IV, II, V, I, III", "IV, I, II, V, III", "IV, II, I, V, III"], "correctAnswer": 3, "subject": "Counselling & psychotherapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Super’s stages: Growth (birth–14) → Exploration (15–24) → Establishment (25–44) → Maintenance (45–64) → Decline/disengagement (65+).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Growth comes first, exploration before establishment, and maintenance before decline.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Super saw career choice as the implementation of the self-concept.</li><li>His ‘life-career rainbow’ shows multiple life roles.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 52, "question": "Lewis Terman’s long-term study, which followed about 1,500 high-IQ children from the 1920s, found that gifted children generally:", "options": ["Had poor social adjustment and frequent mental illness", "Grew up to be healthy, well-adjusted and successful as adults", "Lost their intellectual advantage by adolescence", "Were physically weaker than average"], "correctAnswer": 1, "subject": "Developmental psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Terman’s Genetic Studies of Genius (from 1921) found that the ‘Termites’ were, on average, healthier, better adjusted and more successful than average — challenging the ‘mad genius’ stereotype.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Had poor social adjustment and frequent mental illness — They did not show poor adjustment.</li><li>(C) Lost their intellectual advantage by adolescence — Their advantage largely persisted.</li><li>(D) Were physically weaker than average — They were, if anything, physically healthier.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Terman also produced the Stanford–Binet (1916).</li><li>Not all high-IQ children became eminent; personality and motivation mattered.</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 53, "question": "Money, which can be exchanged for many other rewards, is an example of a:", "options": ["Negative reinforcer", "Generalised (secondary) reinforcer", "Primary reinforcer", "Discriminative stimulus"], "correctAnswer": 1, "subject": "General psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Money gets its value from being paired with many primary reinforcers (food, comfort), so it is a generalised conditioned reinforcer.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Negative reinforcer — Negative reinforcers work by removing something unpleasant.</li><li>(C) Primary reinforcer — Primary reinforcers satisfy biological needs directly.</li><li>(D) Discriminative stimulus — A discriminative stimulus signals that reinforcement is available.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Tokens in a token economy are also secondary reinforcers.</li><li>Praise and grades are common secondary reinforcers.</li></ul>", "examWatch": "Asked in earlier papers; examiners like to test it through a case or a NOT question."}, {"id": 54, "question": "Using interviews, questionnaires and observation to study the same question, so that the results can be cross-checked, is called:", "options": ["Blinding", "Counterbalancing", "Randomisation", "Methodological triangulation"], "correctAnswer": 3, "subject": "Research methods & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Norman Denzin (1970) described triangulation by data, investigator, theory and method. Methodological triangulation uses several methods to check the consistency of findings.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Blinding — Blinding hides group membership.</li><li>(B) Counterbalancing — Counterbalancing controls order effects.</li><li>(C) Randomisation — Randomisation allocates participants by chance.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Triangulation is common in mixed-methods research.</li><li>It increases the credibility of qualitative findings.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 55, "question": "A tall male with small testes, reduced body hair, breast development and often mild learning difficulties most likely has which chromosomal pattern?", "options": ["XXY (Klinefelter syndrome)", "Trisomy 21", "XO (Turner syndrome)", "XYY (Jacobs syndrome)"], "correctAnswer": 0, "subject": "Developmental psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Klinefelter syndrome (47,XXY) causes tall stature, small testes, infertility, gynaecomastia and sometimes language and learning difficulties.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Trisomy 21 — Trisomy 21 is Down syndrome.</li><li>(C) XO (Turner syndrome) — Turner syndrome (45,X) affects females, with short stature.</li><li>(D) XYY (Jacobs syndrome) — XYY males are tall, often with no clear physical signs.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Klinefelter is the most common sex chromosome disorder in males.</li><li>Testosterone treatment helps physical development.</li></ul>", "examWatch": "Questions on this have come before — a quick revision here pays off."}, {"id": 56, "question": "The Leiter International Performance Scale is especially suitable for assessing the intelligence of:", "options": ["Patients with psychosis", "Gifted adolescents only", "Children who are deaf or have little spoken language", "Adults with high verbal ability"], "correctAnswer": 2, "subject": "Psychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The Leiter (Russell Leiter, 1929; Leiter-3, 2013) is completely non-verbal — instructions are given by gesture — so it suits deaf children and those with language or cultural barriers.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Patients with psychosis — It is not designed for psychosis.</li><li>(B) Gifted adolescents only — It is not limited to gifted adolescents.</li><li>(D) Adults with high verbal ability — Verbal tests suit high verbal ability.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Other non-verbal tests: Raven’s Matrices, Draw-a-Person, TONI.</li><li>Non-verbal does not mean culture-free.</li></ul>", "examWatch": "Seen in past papers more than once. Know the difference between the options well."}, {"id": 57, "question": "The receptors in the retina that are most important for vision in dim light are the:", "options": ["Ganglion cells", "Bipolar cells", "Rods", "Cones"], "correctAnswer": 2, "subject": "General psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Rods are very sensitive to low light and give black-and-white vision, mainly in the periphery. Cones need brighter light and give colour vision and sharp detail.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Ganglion cells — Ganglion cells carry signals to the brain; they are not the main light receptors.</li><li>(B) Bipolar cells — Bipolar cells relay signals from receptors to ganglion cells.</li><li>(D) Cones — Cones work in bright light.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The fovea contains only cones.</li><li>Dark adaptation takes about 20–30 minutes as rods recover sensitivity.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 58, "question": "In an ABAB (reversal) single-case design, behaviour improves when treatment starts, worsens when it is withdrawn, and improves again when it is reintroduced. This pattern mainly strengthens:", "options": ["Statistical power", "Generalisation of findings to all populations", "Inter-rater reliability", "Confidence that the treatment caused the change"], "correctAnswer": 3, "subject": "Research methods & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Repeatedly turning the treatment on and off and seeing behaviour follow each time shows experimental control — strong evidence of causation within that person.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Statistical power — Power is a group-statistics concept.</li><li>(B) Generalisation of findings to all populations — Single-case designs do not by themselves give wide generalisation.</li><li>(C) Inter-rater reliability — Rater agreement is a separate issue.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Multiple-baseline designs are used when withdrawal is unethical or impossible.</li><li>Visual analysis of graphs is common in single-case research.</li></ul>", "examWatch": "This area has appeared in previous papers. It may well come in your exam too."}, {"id": 59, "question": "Two-word phrases such as ‘mummy go’ and ‘want milk’, which leave out small grammatical words, are called:", "options": ["Overregularisation", "Telegraphic speech", "Holophrases", "Babbling"], "correctAnswer": 1, "subject": "Developmental psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Telegraphic speech (around 18–24 months) keeps the key content words, like a telegram.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Overregularisation — Overregularisation is applying grammar rules too widely (‘goed’).</li><li>(C) Holophrases — Holophrases are single words expressing a whole idea (around 12 months).</li><li>(D) Babbling — Babbling is repeating consonant–vowel sounds (about 6 months).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Vocabulary grows rapidly after about 18 months (‘naming explosion’).</li><li>Roger Brown studied early grammar.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 60, "question": "A student’s percentile rank of 70 on a test means that the student:", "options": ["Scored higher than about 70% of the norm group", "Scored 70 out of 100", "Is in the top 70% of the class", "Answered 70% of the items correctly"], "correctAnswer": 0, "subject": "Psychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> A percentile rank tells the percentage of people in the norm group who scored below a given score.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Scored 70 out of 100 — A raw score of 70 is not the same as a percentile.</li><li>(C) Is in the top 70% of the class — It means the top 30%, not the top 70%.</li><li>(D) Answered 70% of the items correctly — Percentage correct is a different measure.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The 50th percentile is the median.</li><li>Percentiles are ordinal — differences between them are not equal.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this concept has been asked before in different forms — revise the related points as well."}, {"id": 61, "question": "All of the following are probability sampling methods, EXCEPT:", "options": ["Cluster sampling", "Systematic sampling", "Stratified random sampling", "Snowball sampling"], "correctAnswer": 3, "subject": "Research methods & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Snowball sampling — participants recruit other participants — is a non-probability method, useful for hidden groups such as drug users.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Cluster sampling — Cluster sampling is a probability method.</li><li>(B) Systematic sampling — Systematic sampling with a random start is a probability method.</li><li>(C) Stratified random sampling — Stratified random sampling is a probability method.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Other non-probability methods: convenience, purposive, quota.</li><li>Probability samples allow estimation of sampling error.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 62, "question": "Arrange Bruce Tuckman’s stages of group development in the correct order: I. Norming II. Storming III. Forming IV. Performing", "options": ["III, II, I, IV", "II, III, I, IV", "III, I, II, IV", "III, II, IV, I"], "correctAnswer": 0, "subject": "Counselling & psychotherapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Tuckman (1965): Forming (orientation) → Storming (conflict) → Norming (cohesion and rules) → Performing (productive work). ‘Adjourning’ was added in 1977.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Forming comes first, storming before norming, and performing last.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Group counsellors expect conflict in the storming stage.</li><li>Yalom described group stages and therapeutic factors.</li></ul>", "examWatch": "Asked in earlier papers; examiners like to test it through a case or a NOT question."}, {"id": 63, "question": "<span class=\"pyq-badge\">PYQ</span>Arbitrary zero is the characteristic of which scale?", "options": ["Ratio scale", "Ordinal scale", "Interval scale", "Nominal scale"], "correctAnswer": 2, "subject": "Research methods & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> An interval scale has equal intervals but its zero point is arbitrary, e.g. 0 °C does not mean ‘no temperature’. So ratios (twice as hot) are not meaningful.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Ratio scale — A ratio scale has a true (absolute) zero.</li><li>(B) Ordinal scale — An ordinal scale only ranks.</li><li>(D) Nominal scale — A nominal scale only names categories.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Most psychological test scores are treated as interval data.</li><li>Kelvin temperature is a ratio scale.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 64, "question": "According to Laura Carstensen’s socioemotional selectivity theory, as people grow older and see their remaining time as limited, they tend to:", "options": ["Prefer information-seeking goals over emotional goals", "Focus on fewer, emotionally close relationships and positive experiences", "Withdraw from all relationships as a natural process", "Seek as many new social contacts as possible"], "correctAnswer": 1, "subject": "Developmental psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Carstensen argued that a limited time horizon shifts priorities towards emotionally meaningful goals and close relationships — explaining the ‘positivity effect’ in older adults.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Prefer information-seeking goals over emotional goals — Older adults prioritise emotional over information goals.</li><li>(C) Withdraw from all relationships as a natural process — Total withdrawal reflects disengagement theory, which SST rejects.</li><li>(D) Seek as many new social contacts as possible — Seeking many new contacts is more typical of young people with an open-ended future.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The positivity effect: older adults attend to and remember positive information more.</li><li>Activity theory and disengagement theory are older views of ageing.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 65, "question": "The frustration–aggression hypothesis (1939), which held that frustration always leads to some form of aggression, was proposed by:", "options": ["Albert Bandura", "Leonard Berkowitz", "Konrad Lorenz", "Dollard, Doob, Miller, Mowrer and Sears"], "correctAnswer": 3, "subject": "Social psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> John Dollard and colleagues at Yale proposed the hypothesis in Frustration and Aggression (1939). Berkowitz later revised it.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Albert Bandura — Bandura explained aggression through social learning.</li><li>(B) Leonard Berkowitz — Berkowitz revised the hypothesis, adding aggressive cues (the weapons effect).</li><li>(C) Konrad Lorenz — Lorenz saw aggression as an instinct.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Miller (1941) softened it: frustration produces many responses, one of which may be aggression.</li><li>Displacement onto scapegoats is linked to this theory.</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 66, "question": "Ramesh, 30, has repeated outbursts in which he smashes things and hits people over minor frustrations. The anger is far out of proportion, he feels remorse afterwards, and there is no other mental disorder. The most likely diagnosis is:", "options": ["Intermittent explosive disorder", "Conduct disorder", "Borderline personality disorder", "Bipolar disorder, current episode manic"], "correctAnswer": 0, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Intermittent explosive disorder involves recurrent impulsive aggressive outbursts out of proportion to the trigger, not premeditated, causing distress or problems, from age 6 onwards.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Conduct disorder — Conduct disorder begins in childhood with a broad pattern of rule-breaking.</li><li>(C) Borderline personality disorder — BPD includes unstable relationships, identity and mood, not only explosions.</li><li>(D) Bipolar disorder, current episode manic — Mania needs an episode of elevated mood with other symptoms.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>IED is in the disruptive, impulse-control and conduct disorders chapter.</li><li>CBT for anger and SSRIs are used.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 67, "question": "On Robert Carkhuff’s 5-point scale of empathic understanding, level 3 represents responses that:", "options": ["Add significantly to the client’s feelings beyond what was expressed", "Give advice instead of reflecting feelings", "Are interchangeable with the client’s expressed feelings and meaning — the minimum level of facilitative empathy", "Ignore or detract from the client’s feelings"], "correctAnswer": 2, "subject": "Counselling & psychotherapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Carkhuff’s levels: 1–2 detract from the client’s message; 3 is interchangeable (accurate, minimally facilitative); 4–5 add deeper understanding.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Add significantly to the client’s feelings beyond what was expressed — Additive responses are levels 4–5.</li><li>(B) Give advice instead of reflecting feelings — Advice-giving is not part of the empathy scale.</li><li>(D) Ignore or detract from the client’s feelings — Detracting responses are levels 1–2.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Carkhuff built on Truax and Rogers’ research on core conditions.</li><li>Additive empathy is similar to Egan’s ‘advanced empathy’.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 68, "question": "In a class, no student asks a question about a confusing lecture because each assumes everyone else has understood. This is an example of:", "options": ["Social facilitation", "Pluralistic ignorance", "Groupthink", "Deindividuation"], "correctAnswer": 1, "subject": "Social psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Pluralistic ignorance is when people privately disagree or are confused but wrongly assume others feel differently, so no one acts. It is part of why bystanders fail to help.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Social facilitation — Social facilitation is better performance in front of others.</li><li>(C) Groupthink — Groupthink is a group decision process that suppresses dissent.</li><li>(D) Deindividuation — Deindividuation is loss of self-awareness in crowds.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Latané and Darley linked pluralistic ignorance with bystander inaction.</li><li>Prentice and Miller studied it in student drinking norms.</li></ul>", "examWatch": "Questions on this have come before — a quick revision here pays off."}, {"id": 69, "question": "Questionnaires sometimes include items that are rarely true of anyone (e.g. ‘I have never told a lie’) mainly to detect:", "options": ["Socially desirable or defensive responding", "Random guessing on a timed test", "Low intelligence", "Reading difficulties"], "correctAnswer": 0, "subject": "Psychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Such ‘lie scale’ items (e.g. the MMPI L scale, EPQ Lie scale) catch people who present themselves in an overly favourable light.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Random guessing on a timed test — Random responding is detected by inconsistency scales.</li><li>(C) Low intelligence — They are not designed to detect low intelligence.</li><li>(D) Reading difficulties — Reading problems are checked differently.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Validity scales help judge whether a profile can be interpreted.</li><li>Forced-choice formats are another way to reduce social desirability.</li></ul>", "examWatch": "Seen in past papers more than once. Know the difference between the options well."}, {"id": 70, "question": "Two days after stopping heroin, Sameer has watering eyes, a runny nose, frequent yawning, dilated pupils, goose flesh, diarrhoea and body aches. This picture is typical of:", "options": ["Cannabis intoxication", "Alcohol withdrawal", "Opioid withdrawal", "Opioid intoxication"], "correctAnswer": 2, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Opioid withdrawal resembles a bad flu: lacrimation, rhinorrhoea, yawning, dilated pupils, piloerection (‘cold turkey’), diarrhoea and aches. It is very unpleasant but rarely life-threatening.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Cannabis intoxication — Cannabis intoxication causes red eyes, increased appetite and slowed time sense.</li><li>(B) Alcohol withdrawal — Alcohol withdrawal causes tremor, sweating and may lead to seizures or delirium.</li><li>(D) Opioid intoxication — Opioid intoxication causes pinpoint pupils, drowsiness and slowed breathing.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Naloxone reverses opioid overdose.</li><li>Buprenorphine and methadone are used for opioid substitution therapy.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 71, "question": "The directive, ‘clinical’ or trait-and-factor approach to counselling, in which the counsellor analyses data and advises the client, is mainly associated with:", "options": ["Carl Rogers", "Frederick Thorne", "Albert Ellis", "E.G. Williamson"], "correctAnswer": 3, "subject": "Counselling & psychotherapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> E.G. Williamson (Minnesota) developed directive counselling, based on Frank Parsons’ trait-and-factor idea: analysis, synthesis, diagnosis, prognosis, counselling and follow-up.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Carl Rogers — Rogers developed non-directive counselling.</li><li>(B) Frederick Thorne — Thorne developed eclectic counselling.</li><li>(C) Albert Ellis — Ellis developed REBT.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Frank Parsons is called the father of vocational guidance (1909).</li><li>Directive counselling is counsellor-centred.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 72, "question": "Stevens’ power law, which relates perceived magnitude to physical intensity raised to a power, was based on the method of:", "options": ["Method of constant stimuli", "Magnitude estimation", "Method of adjustment", "Method of limits"], "correctAnswer": 1, "subject": "General psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> S.S. Stevens asked people to give numbers in proportion to how strong a stimulus seemed (magnitude estimation) and found that sensation = k × intensity^n.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Method of constant stimuli — The method of constant stimuli presents fixed stimuli in random order.</li><li>(C) Method of adjustment — The method of adjustment lets the observer adjust the stimulus.</li><li>(D) Method of limits — The method of limits finds thresholds by increasing or decreasing a stimulus step by step.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The exponent is below 1 for brightness and above 1 for electric shock.</li><li>Fechner’s law is logarithmic; Stevens’ law is a power function.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 73, "question": "A counsellor is asked to counsel her close friend’s husband about his depression. The main ethical concern is:", "options": ["Fee-splitting", "Breach of confidentiality only", "A dual (multiple) relationship that may impair objectivity", "Lack of informed consent"], "correctAnswer": 2, "subject": "Counselling & psychotherapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> A dual relationship exists when the counsellor has another significant relationship with the client. It can harm objectivity and exploit the client, so it should be avoided where possible.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Fee-splitting — Fee-splitting is a financial ethics issue.</li><li>(B) Breach of confidentiality only — Confidentiality is a concern, but the core problem is the dual relationship.</li><li>(D) Lack of informed consent — Consent can still be given; the problem lies in the relationship itself.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Sexual relationships with clients are always prohibited.</li><li>Referral to another professional is the usual solution.</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 74, "question": "Arjun, a bodybuilder, spends hours in the gym and believes his body is too small and not muscular enough, though others see him as very muscular. The DSM-5 diagnosis is body dysmorphic disorder with the specifier:", "options": ["With muscle dysmorphia", "With absent insight", "With anabolic steroid use", "With poor insight"], "correctAnswer": 0, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> ‘With muscle dysmorphia’ is used when the person is preoccupied with the idea that their body build is too small or not muscular enough.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) With absent insight — Absent insight would mean delusional conviction.</li><li>(C) With anabolic steroid use — Steroid use is not a DSM-5 specifier for BDD.</li><li>(D) With poor insight — An insight specifier would describe how convinced he is — the main feature here is muscle preoccupation.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>BDD is in the obsessive-compulsive and related disorders chapter.</li><li>Muscle dysmorphia is sometimes called ‘reverse anorexia’.</li></ul>", "examWatch": "This angle is new, but the topic around it is popular with examiners — don’t skip it."}, {"id": 75, "question": "Gerard Egan’s ‘SOLER’ guidelines for attending to a client include all of the following, EXCEPT:", "options": ["Lean slightly towards the client", "Sit squarely facing the client", "Open posture", "Speak first in every exchange"], "correctAnswer": 3, "subject": "Counselling & psychotherapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> SOLER = Sit squarely, Open posture, Lean towards the client, Eye contact, Relaxed. Speaking first is not one of them.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Lean slightly towards the client — Leaning towards the client is the L.</li><li>(B) Sit squarely facing the client — Sitting squarely is the S.</li><li>(C) Open posture — Open posture is the O.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>E = maintain good eye contact; R = be relaxed.</li><li>Egan wrote The Skilled Helper (1975).</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 76, "question": "All of the following are classified as paraphilic disorders in DSM-5, EXCEPT:", "options": ["Voyeuristic disorder", "Pyromania", "Fetishistic disorder", "Frotteuristic disorder"], "correctAnswer": 1, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Pyromania (deliberate fire-setting for tension relief or gratification) is an impulse-control disorder, not a paraphilia. Voyeuristic (watching), frotteuristic (touching or rubbing against non-consenting people) and fetishistic disorders are paraphilic disorders.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Voyeuristic disorder — Voyeuristic disorder is a paraphilic disorder.</li><li>(C) Fetishistic disorder — Fetishistic disorder is a paraphilic disorder.</li><li>(D) Frotteuristic disorder — Frotteuristic disorder is a paraphilic disorder.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>DSM-5 separates a paraphilia (unusual interest) from a paraphilic disorder (causing distress or harm).</li><li>Other paraphilic disorders: exhibitionistic, sexual masochism and sadism, pedophilic, transvestic. Gender dysphoria is not a paraphilia either.</li></ul>", "examWatch": "An ‘outlier’-type question. Papers include a few of these every year to separate toppers — one mark like this can change your rank."}, {"id": 77, "question": "Wechsler noted that some subtests (e.g. Vocabulary, Information) resist the effects of age and brain damage, while others (e.g. Digit Symbol, Block Design) decline. These were called:", "options": ["Speed and power tests", "‘Hold’ and ‘don’t hold’ tests, used to estimate deterioration", "Verbal and performance tests", "Fluid and crystallised indices"], "correctAnswer": 1, "subject": "Psychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Wechsler’s Deterioration Index compared ‘hold’ subtests (stable) with ‘don’t hold’ subtests (declining) to estimate cognitive deterioration.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Speed and power tests — Speed and power describe how tests are timed.</li><li>(C) Verbal and performance tests — The verbal–performance split is a different grouping.</li><li>(D) Fluid and crystallised indices — Fluid and crystallised indices are later theoretical terms.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Premorbid IQ is now often estimated with reading tests (e.g. NART).</li><li>‘Hold’ tests reflect crystallised knowledge.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 78, "question": "A researcher picks every 10th name from an alphabetical list of 1,000 students after a random start. This is:", "options": ["Simple random sampling", "Cluster sampling", "Systematic sampling", "Quota sampling"], "correctAnswer": 2, "subject": "Research methods & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Systematic sampling picks every kth unit (here k = 10) after a random start. It is simple but can be biased if the list has a repeating pattern.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Simple random sampling — Simple random sampling gives every unit an equal, independent chance (e.g. lottery or random numbers).</li><li>(B) Cluster sampling — Cluster sampling picks whole groups.</li><li>(D) Quota sampling — Quota sampling fills set quotas without random selection.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>k = population size ÷ sample size.</li><li>Periodicity in the list is the main danger.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 79, "question": "According to prospect theory, most people feel losing ₹1,000 more strongly than they feel gaining ₹1,000. This is called:", "options": ["Loss aversion", "Overconfidence", "Anchoring", "Sunk-cost fallacy"], "correctAnswer": 0, "subject": "General psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Kahneman and Tversky’s prospect theory (1979) says that losses loom larger than equal gains (roughly twice as much), which shapes risky choices.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Overconfidence — Overconfidence is overestimating one’s accuracy.</li><li>(C) Anchoring — Anchoring is relying too much on a first number.</li><li>(D) Sunk-cost fallacy — Sunk-cost fallacy is continuing because of past investment.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>People are risk-averse for gains and risk-seeking for losses.</li><li>Framing choices as losses or gains changes decisions (the ‘Asian disease’ problem).</li></ul>", "examWatch": "This area has appeared in previous papers. It may well come in your exam too."}, {"id": 80, "question": "‘Grounded theory’, in which theory is built up from qualitative data rather than tested from the start, was developed by:", "options": ["Egon Guba and Yvonna Lincoln", "Jonathan Smith", "Donald Campbell and Julian Stanley", "Barney Glaser and Anselm Strauss"], "correctAnswer": 3, "subject": "Research methods & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Glaser and Strauss (The Discovery of Grounded Theory, 1967) introduced constant comparison and theoretical sampling to develop theory from data.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Egon Guba and Yvonna Lincoln — Guba and Lincoln set out criteria for qualitative trustworthiness.</li><li>(B) Jonathan Smith — Jonathan Smith developed interpretative phenomenological analysis (IPA).</li><li>(C) Donald Campbell and Julian Stanley — Campbell and Stanley wrote on experimental and quasi-experimental designs.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Coding stages: open, axial and selective.</li><li>Data collection stops at ‘theoretical saturation’.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 81, "question": "According to Kohlberg’s cognitive-developmental view of gender, a child understands that her gender will stay the same even if she wears boy’s clothes or plays boy’s games (gender constancy) by about:", "options": ["2 years", "12 years", "1 year", "5 to 7 years"], "correctAnswer": 3, "subject": "Developmental psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Kohlberg (1966) described stages: gender identity (about 2–3), gender stability (about 3–5) and gender constancy (about 5–7), when the child realises gender does not change with appearance.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) 2 years — At 2 years children are just labelling gender.</li><li>(B) 12 years — 12 years is much later than usual.</li><li>(C) 1 year — 1 year is too early for gender labels.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Gender schema theory (Sandra Bem; Martin and Halverson) is an alternative.</li><li>Social learning theory stresses modelling and reinforcement of gender roles.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this concept has been asked before in different forms — revise the related points as well."}, {"id": 82, "question": "The Mooney Problem Check List is used mainly to:", "options": ["Identify personal problems a student wishes to discuss, such as health, family or school worries", "Measure intelligence in children", "Assess neuropsychological deficits after head injury", "Diagnose psychotic disorders"], "correctAnswer": 0, "subject": "Psychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Ross Mooney’s Problem Check List (1941) lists problems in areas such as health, finances, family, social life and schoolwork. It is a guidance and counselling screening tool.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Measure intelligence in children — It does not measure intelligence.</li><li>(C) Assess neuropsychological deficits after head injury — It is not a neuropsychological test.</li><li>(D) Diagnose psychotic disorders — It is not a diagnostic tool for psychosis.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Checklists are quick to give but depend on honest self-report.</li><li>They help counsellors start discussions.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 83, "question": "Whenever Deepa sees blood or an injection needle, her heart rate first rises and then drops sharply, and she faints. This fainting pattern is characteristic of which type of specific phobia?", "options": ["Situational type", "Blood-injection-injury type", "Natural environment type", "Animal type"], "correctAnswer": 1, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Blood-injection-injury phobia shows a unique ‘diphasic’ response: a brief rise in heart rate and blood pressure, then a vasovagal drop that can cause fainting.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Situational type — Situational phobias (lifts, flying) do not typically cause fainting.</li><li>(C) Natural environment type — Natural environment phobias (heights, storms, water) also do not typically cause fainting.</li><li>(D) Animal type — Animal phobias show the usual fight-or-flight arousal without fainting.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>‘Applied tension’ (Öst) is used to prevent fainting during exposure.</li><li>BII phobia runs strongly in families.</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 84, "question": "G. Stanley Hall described adolescence as a period of:", "options": ["Industry versus inferiority", "Formal operations", "Storm and stress", "Moratorium"], "correctAnswer": 2, "subject": "Developmental psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> In ‘Adolescence’ (1904), G. Stanley Hall called adolescence a time of ‘storm and stress’ (Sturm und Drang) — conflict with parents, mood swings and risky behaviour.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Industry versus inferiority — Industry versus inferiority is Erikson’s school-age stage.</li><li>(B) Formal operations — Formal operations is Piaget’s stage.</li><li>(D) Moratorium — Moratorium is Marcia’s identity status.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Margaret Mead’s Samoa study challenged the idea that storm and stress is universal.</li><li>Hall founded the American Psychological Association (1892).</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 85, "question": "In a distribution, the first quartile (Q1) is 20 and the third quartile (Q3) is 50. The quartile deviation (semi-interquartile range) is:", "options": ["15", "30", "35", "70"], "correctAnswer": 0, "subject": "Research methods & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Quartile deviation = (Q3 − Q1) ÷ 2 = (50 − 20) ÷ 2 = 15.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) 30 — 30 is the interquartile range (Q3 − Q1), not halved.</li><li>(C) 35 — 35 is the midpoint of Q1 and Q3.</li><li>(D) 70 — 70 is Q1 + Q3.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The quartile deviation is used with the median for skewed data.</li><li>The interquartile range covers the middle 50% of scores.</li></ul>", "examWatch": "Asked in earlier papers; examiners like to test it through a case or a NOT question."}, {"id": 86, "question": "Repetitive consonant–vowel sounds such as ‘ba-ba-ba’ or ‘da-da-da’ usually begin around:", "options": ["3 years", "6 months", "1 month", "18 months"], "correctAnswer": 1, "subject": "Developmental psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Canonical babbling begins at about 6 months. Deaf infants also begin vocal babbling but it fades; deaf infants exposed to sign language ‘babble’ with their hands.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) 3 years — At 3 years children speak in sentences.</li><li>(C) 1 month — At 1 month infants mainly cry and coo.</li><li>(D) 18 months — At 18 months children use words and early phrases.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Cooing (vowel sounds) appears at about 2 months.</li><li>First words usually appear around 12 months.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}, {"id": 87, "question": "In Treisman’s feature integration theory, a red ‘X’ ‘pops out’ instantly among green ‘X’s, but finding a red ‘X’ among red ‘O’s and green ‘X’s takes longer as the number of items grows. This is because:", "options": ["Peripheral vision cannot detect colour", "Colour is processed only after shape", "Single features are detected in parallel, but combining features (conjunction search) needs focused, serial attention", "Memory for colours is poorer than memory for shapes"], "correctAnswer": 2, "subject": "General psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Treisman and Gelade (1980): basic features are registered automatically in parallel (pre-attentive stage), but binding features into objects needs focused attention, item by item.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Peripheral vision cannot detect colour — Peripheral vision can detect colour differences.</li><li>(B) Colour is processed only after shape — Colour and shape are both processed early, in parallel.</li><li>(D) Memory for colours is poorer than memory for shapes — Memory is not the explanation.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>‘Illusory conjunctions’ occur when attention is overloaded.</li><li>Feature search time stays flat; conjunction search time rises with display size.</li></ul>", "examWatch": "Questions on this have come before — a quick revision here pays off."}, {"id": 88, "question": "The term ‘alexithymia’ — difficulty identifying and describing one’s own emotions — was introduced in 1973 by:", "options": ["Franz Alexander", "Hans Selye", "John Nemiah alone", "Peter Sifneos"], "correctAnswer": 3, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Peter Sifneos coined ‘alexithymia’ (literally ‘no words for feelings’) from his work with psychosomatic patients; he worked closely with John Nemiah.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Franz Alexander — Franz Alexander described the ‘holy seven’ psychosomatic disorders.</li><li>(B) Hans Selye — Selye described the general adaptation syndrome.</li><li>(C) John Nemiah alone — Nemiah worked with Sifneos but did not coin the term alone.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The Toronto Alexithymia Scale (TAS-20) measures it.</li><li>Alexithymia is common in somatic symptom and autism spectrum conditions.</li></ul>", "examWatch": "Seen in past papers more than once. Know the difference between the options well."}, {"id": 89, "question": "Ghrelin, a hormone that increases hunger before meals, is released mainly by the:", "options": ["Pancreas", "Thyroid gland", "Adrenal cortex", "Stomach"], "correctAnswer": 3, "subject": "General psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Ghrelin is secreted by the empty stomach and signals hunger to the hypothalamus. Leptin from fat cells signals satiety.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Pancreas — The pancreas releases insulin and glucagon.</li><li>(B) Thyroid gland — The thyroid releases thyroxine.</li><li>(C) Adrenal cortex — The adrenal cortex releases cortisol.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Ghrelin levels rise before meals and fall after eating.</li><li>Sleep loss raises ghrelin and lowers leptin.</li></ul>", "examWatch": "This area has appeared in previous papers. It may well come in your exam too."}, {"id": 90, "question": "On a stanine scale, scores range from:", "options": ["1 to 10, with a mean of 5.5", "0 to 100, with a mean of 50", "1 to 9, with a mean of 5", "20 to 80, with a mean of 50"], "correctAnswer": 2, "subject": "Psychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> ‘Stanine’ = standard nine. It divides the normal curve into 9 bands, with a mean of 5 and SD of about 2.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) 1 to 10, with a mean of 5.5 — Stens run from 1 to 10 with a mean of 5.5.</li><li>(B) 0 to 100, with a mean of 50 — 0–100 with mean 50 does not describe stanines.</li><li>(D) 20 to 80, with a mean of 50 — T-scores have a mean of 50 and SD 10 (usually 20–80).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Stanines were first used by the US Air Force in World War II.</li><li>Stanine 5 covers the middle 20% of scores.</li></ul>", "examWatch": "Not asked directly yet, but it sits right next to frequently asked topics — it may appear in a new form."}, {"id": 91, "question": "<span class=\"pyq-badge\">PYQ</span>‘Reinforcement will have positive effect on learning’ is an example of which type of hypothesis?", "options": ["Null and directional", "Alternate and directional", "Null and non-directional", "Alternate and non-directional"], "correctAnswer": 1, "subject": "Research methods & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> It predicts an effect (alternate/research hypothesis) and states its direction (positive), so it is a directional alternate hypothesis.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Null and directional — A null hypothesis predicts no effect.</li><li>(C) Null and non-directional — A null hypothesis predicts no effect, and this one has a direction.</li><li>(D) Alternate and non-directional — This one does state a direction.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>A directional hypothesis uses a one-tailed test.</li><li>Non-directional: ‘Reinforcement will affect learning’ (two-tailed).</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 92, "question": "Which of these is an open question?", "options": ["‘How have things been at home since the move?’", "‘Is your job stressful?’", "‘Are you angry with your brother?’", "‘Did you sleep well last night?’"], "correctAnswer": 0, "subject": "Counselling & psychotherapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Open questions (often starting with ‘how’ or ‘what’) invite the client to talk freely. Closed questions can be answered with ‘yes’ or ‘no’.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) ‘Is your job stressful?’ — This can be answered yes or no.</li><li>(C) ‘Are you angry with your brother?’ — This can be answered yes or no.</li><li>(D) ‘Did you sleep well last night?’ — This can be answered yes or no.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Closed questions are useful for specific facts.</li><li>Too many ‘why’ questions can sound blaming.</li></ul>", "examWatch": "A favourite of paper-setters — asked again and again in different exams. Expect it in some form."}, {"id": 93, "question": "The idea that the language we speak shapes or limits how we think and perceive the world is known as the:", "options": ["Dual-coding theory", "Universal grammar", "Sapir–Whorf hypothesis (linguistic relativity)", "Language acquisition device"], "correctAnswer": 2, "subject": "General psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Edward Sapir and Benjamin Lee Whorf proposed linguistic relativity. The strong version (language determines thought) is rejected; a weak version (language influences thought) has some support.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Dual-coding theory — Dual-coding theory (Paivio) is about verbal and imagery codes in memory.</li><li>(B) Universal grammar — Universal grammar is Chomsky’s idea of shared grammatical principles.</li><li>(D) Language acquisition device — The LAD is Chomsky’s innate language-learning capacity.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Eleanor Rosch’s colour studies with the Dani people questioned the strong version.</li><li>Piaget saw thought as coming before language; Vygotsky saw them as merging.</li></ul>", "examWatch": "Asked several times across papers. The questions are usually direct, so these are easy marks if you revise."}, {"id": 94, "question": "The standard deviation of a set of scores is the:", "options": ["Square root of the variance", "Square of the variance", "Average of the deviations without squaring", "Difference between highest and lowest scores"], "correctAnswer": 0, "subject": "Research methods & statistics", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Variance is the average of squared deviations from the mean; the standard deviation is its square root, bringing it back to the original units.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Square of the variance — Squaring the variance is meaningless here.</li><li>(C) Average of the deviations without squaring — Raw deviations from the mean always add up to zero.</li><li>(D) Difference between highest and lowest scores — The difference between highest and lowest scores is the range.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>SD is the most widely used measure of variability.</li><li>About 68% of scores lie within ±1 SD in a normal distribution.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this area is asked often. Learn the related points above too."}, {"id": 95, "question": "In the habituation method, a baby looks at a picture less and less, then looks longer when a new picture appears. The renewed looking shows that the baby:", "options": ["Has developed object permanence", "Prefers familiar stimuli", "Has forgotten the first picture", "Can tell the new stimulus apart from the old one"], "correctAnswer": 3, "subject": "Developmental psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Habituation is a decrease in response to a repeated stimulus; dishabituation (renewed interest) to a new stimulus shows that the infant notices the difference.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Has developed object permanence — Object permanence is tested differently (hidden objects).</li><li>(B) Prefers familiar stimuli — Babies in this paradigm show a novelty preference.</li><li>(C) Has forgotten the first picture — Forgetting would not produce renewed interest only for a new picture.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Robert Fantz’s preferential looking method is a related technique.</li><li>Habituation speed in infancy modestly predicts later IQ.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this concept has been asked before in different forms — revise the related points as well."}, {"id": 96, "question": "In the Johari window, the area of the self that is known to others but not known to oneself is the:", "options": ["Hidden area", "Blind area", "Open area", "Unknown area"], "correctAnswer": 1, "subject": "Counselling & psychotherapy", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Joseph Luft and Harrington Ingham (1955) described four panes: open (known to self and others), blind (known to others only), hidden (known to self only) and unknown (known to neither).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Hidden area — The hidden area is known only to oneself.</li><li>(C) Open area — The open area is known to both.</li><li>(D) Unknown area — The unknown area is known to neither.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Feedback shrinks the blind area; self-disclosure shrinks the hidden area.</li><li>It is used in group work and training.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a likely new area. Learn the key points above."}, {"id": 97, "question": "During an episode of illness, Vikram talks rapidly and loudly, cannot be interrupted, and jumps from topic to topic. His speech is best described as:", "options": ["Echolalia", "Poverty of speech", "Perseveration", "Pressure of speech"], "correctAnswer": 3, "subject": "Clinical psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Pressure of speech — rapid, excessive speech that is hard to interrupt — is typical of mania.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Echolalia — Echolalia is repeating others’ words.</li><li>(B) Poverty of speech — Poverty of speech (alogia) is reduced speech.</li><li>(C) Perseveration — Perseveration is repeating the same response inappropriately.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Flight of ideas often accompanies pressure of speech in mania.</li><li>Logorrhoea is another term for excessive talking.</li></ul>", "examWatch": "Examiners return to this topic year after year. Make sure the basics are rock-solid."}, {"id": 98, "question": "All of the following are monocular (one-eye) cues to depth, EXCEPT:", "options": ["Linear perspective", "Interposition", "Convergence", "Texture gradient"], "correctAnswer": 2, "subject": "General psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Convergence — the inward turning of both eyes to look at a near object — needs two eyes, so it is a binocular cue. The others work with one eye.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Linear perspective — Linear perspective (parallel lines meeting in the distance) is monocular.</li><li>(B) Interposition — Interposition (overlap) is monocular.</li><li>(D) Texture gradient — Texture gradient (texture getting finer with distance) is monocular.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Retinal disparity is the other main binocular cue.</li><li>Artists use monocular cues to show depth on flat paper.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a high-frequency area — it has been asked several times in different papers. Keep it at your fingertips."}, {"id": 99, "question": "Wariness or distress when an unfamiliar person approaches (stranger anxiety) typically first appears around:", "options": ["1 month", "6 to 8 months", "5 years", "3 years"], "correctAnswer": 1, "subject": "Developmental psychology", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Stranger anxiety usually emerges at about 6–8 months and peaks around the end of the first year, as the infant forms specific attachments.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) 1 month — At 1 month infants do not yet show it.</li><li>(C) 5 years — By 5 years it is no longer typical.</li><li>(D) 3 years — By 3 years it is usually declining.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Separation anxiety peaks around 10–18 months.</li><li>Both are normal signs of attachment.</li></ul>", "examWatch": "Asked in earlier papers; examiners like to test it through a case or a NOT question."}, {"id": 100, "question": "The Holtzman Inkblot Technique differs from the Rorschach mainly because it:", "options": ["Uses 45 inkblots and allows only one response per card, making scoring more reliable", "Is scored only for content, not for form or colour", "Asks the person to tell a story about each card", "Uses coloured pictures of people instead of inkblots"], "correctAnswer": 0, "subject": "Psychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Wayne Holtzman (1961) designed two parallel forms of 45 inkblots each, with one response per card, to improve standardisation and reliability.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Is scored only for content, not for form or colour — It is scored for form, colour, movement and content, among others.</li><li>(C) Asks the person to tell a story about each card — Stories are told in the TAT and CAT.</li><li>(D) Uses coloured pictures of people instead of inkblots — Pictures of people are used in the TAT.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The Rorschach has 10 cards and allows many responses per card.</li><li>Parallel forms allow retesting.</li></ul>", "examWatch": "This topic keeps coming back in entrance papers, often with a small change in wording. Revise it well."}];
